using System.Collections.Generic;
using UnityEngine;

// Remodeled unit art with a 4-frame idle loop, generated by Tools/PixelArt (`node heroes.js --export`, `node enemies.js --export`).
//   Heroes:  Resources/Heroes/<id>_<frame>.png, 22x27 (exact 4x in the 88x108 combat box), keyed by the Art row arrays
//            so every existing `sprite = Art.X` reference picks them up.
//   Enemies: Resources/Enemies/<id>_<frame>.png, 24x26 (4x in 96x104) or 48x60 for bosses (4x in 192x240), keyed by enemy id,
//            since several roster enemies share one Art row array. Legacy enemies fall back to the closest new art by rows.
// Units with no remodeled art keep drawing from their rows.
namespace Obscure
{
    public static class UnitArt
    {
        public static readonly float[] IdleDelays = { 0.32f, 0.18f, 0.32f, 0.18f };
        const float IdleLength = 1f; // sum of IdleDelays

        static readonly Dictionary<string[], string> heroes = new Dictionary<string[], string>
        {
            [Art.Knight] = "knight",
            [Art.Fighter] = "fighter",
            [Art.Barbarian] = "barbarian",
            [Art.MartialArtist] = "martial_artist",
            [Art.Rogue] = "rogue",
            [Art.Ranger] = "ranger",
            [Art.Healer] = "cleric", // shared by the Cleric class and the legacy Healer
            [Art.Mage] = "wizard",   // shared by the Wizard class and the legacy Mage
            [Art.Warlock] = "warlock",
            [Art.Druid] = "druid",
        };

        static readonly HashSet<string> enemies = new HashSet<string>
        {
            "hollow_squire", "gravebound_archer", "cinder_wisp", "soulbound_hound", "possessed_royal_guard",
            "crypt_leech", "forgotten_militia", "soul_reaper", "royal_ossuary_knight", "zoroa_p1", "zoroa_p2",
        };

        // Legacy enemies (Skeleton Warrior, Cursed Knight, Abyssal Warden) reuse the closest Dungeon 1 art.
        static readonly Dictionary<string[], string> legacyEnemies = new Dictionary<string[], string>
        {
            [Art.Skeleton] = "hollow_squire",
            [Art.CursedKnight] = "royal_ossuary_knight",
            [Art.Warden] = "zoroa_p1",
        };

        static readonly Dictionary<string, Texture2D[]> cache = new Dictionary<string, Texture2D[]>();

        // Hero idle frames for a sprite's rows, or null when there is no remodeled art for it.
        public static Texture2D[] Idle(string[] rows) =>
            rows != null && heroes.TryGetValue(rows, out var id) ? Load("Heroes/" + id) : null;

        // Enemy idle frames by enemy id (falling back to legacy rows), or null to keep the row art.
        public static Texture2D[] Enemy(string enemyId, string[] rows)
        {
            if (enemyId != null && enemies.Contains(enemyId)) return Load("Enemies/" + enemyId);
            return rows != null && legacyEnemies.TryGetValue(rows, out var id) ? Load("Enemies/" + id) : null;
        }

        static Texture2D[] Load(string path)
        {
            if (cache.TryGetValue(path, out var frames) && (frames == null || frames[0] != null)) return frames;
            frames = new Texture2D[IdleDelays.Length];
            for (int i = 0; i < frames.Length; i++)
            {
                frames[i] = Resources.Load<Texture2D>($"{path}_{i}");
                if (frames[i] == null) return cache[path] = null;
                frames[i].filterMode = FilterMode.Point;
            }
            return cache[path] = frames;
        }

        // Frame index of the idle loop at time t (seconds).
        public static int FrameAt(float t)
        {
            t = Mathf.Repeat(t, IdleLength);
            for (int i = 0; i < IdleDelays.Length; i++)
            {
                if (t < IdleDelays[i]) return i;
                t -= IdleDelays[i];
            }
            return IdleDelays.Length - 1;
        }
    }
}
